"use client"

import { RouteError } from "@/components/route-error"

export default function RouteErrorPage({
  error,
  reset,
}: Readonly<{
  error: Error & { digest?: string }
  reset: () => void
}>) {
  return <RouteError error={error} reset={reset} />
}

import type { Metadata } from "next"

import { BankNav } from "@/app/templates/bank/_components/bank-nav"
import { BANK_NAME } from "@/app/templates/bank/_data/site"
import { profileScopeAttributes } from "@/components/profile-scope"

export const metadata: Metadata = {
  title: `${BANK_NAME} · doksam-ui 템플릿`,
  description: "service 프로필(ocean · noto-sans-kr)을 강제 적용한 리테일 뱅크 포털 홈페이지 템플릿.",
}

/**
 * app/templates/bank/** 전체를 service 프로필(ocean 테마 + noto-sans-kr 폰트)로
 * 스코프한다 — app/templates/saas/layout.tsx 와 동일한 컨테이너 스코핑 기법
 * (프로필 축 data-*). 은행은 신뢰감을 주는 블루(ocean) 계열이 정석이라
 * 이슈에서 지정한 프로필을 그대로 강제 적용한다.
 *
 * app/layout.tsx(루트)는 건드리지 않는다.
 */
export default function BankTemplateLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <div {...profileScopeAttributes("service")} className="flex flex-col bg-background font-sans text-foreground">
      <BankNav />
      <div className="flex flex-col gap-10 px-4 py-6 sm:px-6 sm:py-10">{children}</div>
    </div>
  )
}

import { RouteLoading } from "@/components/route-loading"

export default function Loading() {
  return <RouteLoading />
}

"use client"

import * as React from "react"
import Link from "next/link"
import { ArrowRightIcon } from "@phosphor-icons/react/dist/ssr"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  type CarouselApi,
} from "@/components/ui/carousel"
import { HERO_SLIDES } from "@/app/templates/bank/_data/hero"

/**
 * 히어로 프로모 캐러셀 — 마스코트는 이미지 대신 슬라이드별 Phosphor 아이콘 +
 * CSS 그라디언트 원형 도형으로 추상 표현한다. 도트 인디케이터로 현재 슬라이드를
 * 표시하고 클릭으로 이동할 수 있다.
 */
export function HeroCarousel() {
  const [api, setApi] = React.useState<CarouselApi>()
  const [current, setCurrent] = React.useState(0)

  React.useEffect(() => {
    if (!api) return
    const onSelect = () => setCurrent(api.selectedScrollSnap())
    api.on("select", onSelect)
    return () => {
      api.off("select", onSelect)
    }
  }, [api])

  return (
    <section aria-label="프로모 배너" className="relative">
      <Carousel setApi={setApi} opts={{ loop: true }}>
        <CarouselContent>
          {HERO_SLIDES.map((slide) => {
            const Icon = slide.icon
            return (
              <CarouselItem key={slide.id}>
                <div className="relative overflow-hidden rounded-2xl border border-border bg-card px-6 py-12 sm:px-12 sm:py-16">
                  <div
                    aria-hidden
                    className={cn(
                      "pointer-events-none absolute -top-16 -right-16 size-64 rounded-full bg-gradient-to-br blur-2xl",
                      slide.toneClass,
                    )}
                  />
                  <div className="relative z-10 flex flex-col items-start gap-4 sm:max-w-xl">
                    <div className="flex items-center gap-3">
                      <span className="flex size-12 items-center justify-center rounded-full bg-primary/10 text-primary">
                        <Icon size={26} weight="duotone" />
                      </span>
                      <span className="text-sm font-semibold text-primary">{slide.eyebrow}</span>
                    </div>
                    <h1 className="text-2xl font-bold tracking-tight text-balance sm:text-3xl">{slide.title}</h1>
                    <p className="text-sm text-pretty text-muted-foreground sm:text-base">{slide.subtitle}</p>
                    <Button asChild>
                      <Link href={slide.ctaHref}>
                        {slide.ctaLabel}
                        <ArrowRightIcon size={16} weight="bold" />
                      </Link>
                    </Button>
                  </div>
                </div>
              </CarouselItem>
            )
          })}
        </CarouselContent>
      </Carousel>

      <div role="tablist" aria-label="배너 선택" className="mt-3 flex items-center justify-center gap-2">
        {HERO_SLIDES.map((slide, index) => (
          <button
            key={slide.id}
            type="button"
            role="tab"
            aria-selected={current === index}
            aria-label={`${index + 1}번째 배너: ${slide.title}`}
            onClick={() => api?.scrollTo(index)}
            className={cn(
              "h-2 rounded-full transition-[width,background-color]",
              current === index ? "w-6 bg-primary" : "w-2 bg-muted-foreground/30 hover:bg-muted-foreground/50",
            )}
          />
        ))}
      </div>
    </section>
  )
}

import Link from "next/link"

import { PRODUCT_CATEGORIES } from "@/app/templates/bank/_data/product-categories"

export function ProductCategories() {
  return (
    <section aria-label="금융상품 카테고리" className="flex flex-col gap-4">
      <h2 className="text-lg font-semibold tracking-tight text-foreground">금융상품</h2>
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        {PRODUCT_CATEGORIES.map((category) => {
          const Icon = category.icon
          return (
            <Link
              key={category.key}
              href={category.href}
              className="flex flex-col items-center gap-2 rounded-xl p-3 text-center transition-colors hover:bg-muted/60"
            >
              <span className="flex size-16 items-center justify-center rounded-full bg-primary/10 text-primary">
                <Icon size={28} weight="duotone" />
              </span>
              <span className="text-sm font-medium text-foreground">{category.label}</span>
            </Link>
          )
        })}
      </div>
    </section>
  )
}

import Link from "next/link"

import { Badge } from "@/components/ui/badge"
import { Card, CardContent } from "@/components/ui/card"
import { PROMO_CARDS } from "@/app/templates/bank/_data/promos"

export function PromoCards() {
  return (
    <section aria-label="프로모션" className="grid grid-cols-1 gap-4 sm:grid-cols-2">
      {PROMO_CARDS.map((promo) => (
        <Link key={promo.id} href={promo.href}>
          <Card className="h-full transition-colors hover:bg-muted/40">
            <CardContent className="flex flex-col gap-2">
              <Badge variant={promo.badge === "EVENT" ? "default" : "secondary"} className="w-fit">
                {promo.badge}
              </Badge>
              <h3 className="text-base font-semibold text-foreground">{promo.title}</h3>
              <p className="text-sm text-muted-foreground">{promo.description}</p>
            </CardContent>
          </Card>
        </Link>
      ))}
    </section>
  )
}

"use client"

import * as React from "react"
import Link from "next/link"

import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import {
  DEFAULT_QUICK_LINK_GROUP,
  QUICK_LINK_GROUPS,
  type QuickLinkGroupKey,
} from "@/app/templates/bank/_data/quick-links"

/** 바로바로서비스 — "예금"/"카드" 토글에 따라 아래 퀵링크 목록이 바뀐다. */
export function QuickLinksPanel() {
  const [group, setGroup] = React.useState<QuickLinkGroupKey>(DEFAULT_QUICK_LINK_GROUP)
  const active = QUICK_LINK_GROUPS[group]

  return (
    <section aria-label="바로바로서비스" className="flex flex-col gap-4 rounded-xl border border-border bg-card p-4 sm:p-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h2 className="text-lg font-semibold tracking-tight text-foreground">바로바로서비스</h2>
        <ToggleGroup
          type="single"
          variant="outline"
          size="sm"
          value={group}
          onValueChange={(value) => value && setGroup(value as QuickLinkGroupKey)}
          aria-label="바로바로서비스 카테고리"
        >
          {(Object.keys(QUICK_LINK_GROUPS) as QuickLinkGroupKey[]).map((key) => (
            <ToggleGroupItem key={key} value={key} aria-label={QUICK_LINK_GROUPS[key].label}>
              {QUICK_LINK_GROUPS[key].label}
            </ToggleGroupItem>
          ))}
        </ToggleGroup>
      </div>

      <ul className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        {active.links.map((link) => {
          const Icon = link.icon
          return (
            <li key={link.key}>
              <Link
                href={link.href}
                className="flex items-center gap-2 rounded-lg border border-border bg-background px-3 py-2.5 text-sm font-medium text-foreground transition-colors hover:bg-muted"
              >
                <Icon size={18} className="text-primary" />
                {link.label}
              </Link>
            </li>
          )
        })}
      </ul>
    </section>
  )
}

"use client"

import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { DEFAULT_QUICK_SERVICE_KEY, QUICK_SERVICE_TABS } from "@/app/templates/bank/_data/quick-services"

/**
 * 퀵서비스 탭바 — "카드등록" 기본 활성. 가로 스크롤로 모바일 대응(그리드 리플로우
 * 대신 탭 특성상 가로 스크롤이 자연스럽다).
 */
export function QuickServiceTabs() {
  return (
    <Tabs defaultValue={DEFAULT_QUICK_SERVICE_KEY} className="w-full">
      <TabsList className="h-auto w-full justify-start gap-1 overflow-x-auto bg-muted/60 p-1">
        {QUICK_SERVICE_TABS.map((tab) => {
          const Icon = tab.icon
          return (
            <TabsTrigger key={tab.key} value={tab.key} className="flex-none gap-1.5 px-3 py-1.5">
              <Icon size={16} />
              {tab.label}
            </TabsTrigger>
          )
        })}
      </TabsList>
      {QUICK_SERVICE_TABS.map((tab) => (
        <TabsContent key={tab.key} value={tab.key} className="px-1 py-2 text-sm text-muted-foreground">
          {tab.description}
        </TabsContent>
      ))}
    </Tabs>
  )
}

/** 상단 유틸바 링크 — 로그인/공동인증센터/고객센터 등 보조 도구 모음. */
